"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { 
  Search, Filter, Trash2, CheckCircle, Reply, 
  MessageSquare, Star, AlertCircle
} from "lucide-react";

// DATA DUMMY
const initialMessages = [
  { 
    id: 1, 
    sender: "Rian (XI RPL 1)", 
    category: "Sarana",
    tagColor: "orange",
    subject: "AC di Lab Komputer Panas", 
    preview: "Assalamualaikum kak, mau lapor AC di Lab 2 mati satu, jadi panas banget pas praktek...", 
    date: "10:45 AM", 
    status: "unread", 
    isStarred: true 
  },
  { 
    id: 2, 
    sender: "Siska (X TKJ 2)", 
    category: "Event", 
    tagColor: "purple",
    subject: "Request Guest Star Pensi", 
    preview: "Kak, tahun ini undang Tulus dong buat pensi sekolah! Pasti tiketnya laku keras...", 
    date: "Kemarin", 
    status: "read",
    isStarred: false 
  },
  { 
    id: 3, 
    sender: "Anonim", 
    category: "Kurikulum", 
    tagColor: "blue",
    subject: "Jadwal Pelajaran Bentrok", 
    preview: "Min, jadwal olahraga kelas kami bentrok sama jam istirahat, mohon ditinjau...", 
    date: "2 Jan", 
    status: "done",
    isStarred: false 
  },
  { 
    id: 4, 
    sender: "Budi (XII OTKP)", 
    category: "Umum", 
    tagColor: "slate",
    subject: "Parkiran Motor Sempit", 
    preview: "Tolong dong parkiran dirapikan lagi, motor sering baret karena desak-desakan...", 
    date: "1 Jan", 
    status: "read",
    isStarred: false 
  },
];

export default function InboxPage() {
  const [messages, setMessages] = useState(initialMessages);
  const [selectedTab, setSelectedTab] = useState("all"); 
  const [searchQuery, setSearchQuery] = useState("");

  const filteredMessages = messages.filter((msg) => {
    const matchesTab = 
      selectedTab === "all" ? msg.status !== "done" : 
      selectedTab === "done" ? msg.status === "done" :
      selectedTab === "unread" ? msg.status === "unread" : true;
    
    const matchesSearch = 
      msg.sender.toLowerCase().includes(searchQuery.toLowerCase()) || 
      msg.subject.toLowerCase().includes(searchQuery.toLowerCase());

    return matchesTab && matchesSearch;
  });

  const handleMarkDone = (id: number) => {
    setMessages(messages.map(m => m.id === id ? { ...m, status: "done" } : m));
  };

  const handleDelete = (id: number) => {
    if(confirm("Hapus pesan ini?")) {
      setMessages(messages.filter(m => m.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      
      {/* HEADER */}
      <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold font-black text-slate-900 dark:text-white tracking-tight">
            Inbox Aspirasi <span className="text-blue-500 text-2xl">📩</span>
          </h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm font-medium">
            Kelola pesan dan laporan siswa secara real-time.
          </p>
        </div>
        
        {/* Search Bar */}
        <div className="relative w-full md:w-80 group">
           <input 
             type="text" 
             placeholder="Cari pengirim atau subjek..." 
             value={searchQuery}
             onChange={(e) => setSearchQuery(e.target.value)}
             className="w-full pl-11 pr-4 py-3 rounded-2xl bg-white dark:bg-[#0f172a]/60 border border-slate-200 dark:border-white/10 focus:ring-2 focus:ring-blue-500/50 outline-none transition-all text-sm font-medium text-slate-700 dark:text-white shadow-sm group-hover:shadow-md"
           />
           <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
        </div>
      </div>

      {/* MAIN CONTAINER */}
      <div className="bg-white dark:bg-[#0f172a]/60 backdrop-blur-xl border border-slate-200 dark:border-white/10 rounded-[2rem] overflow-hidden shadow-sm flex flex-col md:flex-row min-h-[600px]">
        
        {/* LEFT: Sidebar Filter (FIX KONTRAS LIGHT MODE) */}
        {/* Perubahan: bg-slate-100 (Solid Gray) untuk Light Mode biar beda sama konten kanan */}
        <div className="w-full md:w-72 border-b md:border-b-0 md:border-r border-slate-200 dark:border-white/5 p-6 bg-slate-100 dark:bg-white/5 flex flex-col gap-6">
           
           <button className="w-full py-3.5 bg-blue-600 hover:bg-blue-700 active:scale-95 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-500/30 flex items-center justify-center gap-2 transition-all">
              <Filter size={18} /> Filter Lanjutan
           </button>

           <div className="space-y-2">
              <p className="text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest px-3 mb-1">Folder</p>
              {[
                { id: "all", label: "Kotak Masuk", icon: MessageSquare, count: messages.filter(m => m.status !== "done").length },
                { id: "unread", label: "Belum Dibaca", icon: AlertCircle, count: messages.filter(m => m.status === "unread").length },
                { id: "done", label: "Arsip Selesai", icon: CheckCircle, count: messages.filter(m => m.status === "done").length },
              ].map((tab) => (
                <button 
                  key={tab.id}
                  onClick={() => setSelectedTab(tab.id)}
                  className={`w-full flex items-center justify-between px-4 py-3 rounded-xl text-sm font-bold transition-all
                    ${selectedTab === tab.id 
                      // Active: Light Mode = Putih + Shadow (Card Look), Dark Mode = Putih Transparan
                      ? "bg-white dark:bg-white/10 text-blue-600 dark:text-white shadow-sm ring-1 ring-black/5 dark:ring-white/10" 
                      // Inactive: Text lebih gelap biar jelas
                      : "text-slate-600 dark:text-slate-400 hover:bg-white/50 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-white"
                    }
                  `}
                >
                   <div className="flex items-center gap-3">
                      <tab.icon size={18} className={selectedTab === tab.id ? "text-blue-500 dark:text-blue-400" : "opacity-70"} />
                      {tab.label}
                   </div>
                   {tab.count > 0 && (
                     <span className={`text-[10px] font-extrabold px-2.5 py-0.5 rounded-full 
                       ${selectedTab === tab.id ? "bg-blue-100 text-blue-600 dark:bg-blue-600 dark:text-white" : "bg-slate-200 text-slate-600 dark:bg-slate-700 dark:text-slate-300"}
                     `}>
                       {tab.count}
                     </span>
                   )}
                </button>
              ))}
           </div>
        </div>

        {/* RIGHT: Message List */}
        <div className="flex-1 p-4 md:p-6 bg-white dark:bg-transparent overflow-y-auto">
           
           <div className="space-y-3">
             <AnimatePresence>
               {filteredMessages.length > 0 ? (
                 filteredMessages.map((msg) => (
                   <motion.div 
                     key={msg.id}
                     initial={{ opacity: 0, y: 10 }}
                     animate={{ opacity: 1, y: 0 }}
                     exit={{ opacity: 0, scale: 0.95 }}
                     layout
                     className={`group relative p-5 rounded-2xl border transition-all cursor-pointer hover:shadow-lg hover:-translate-y-0.5
                       ${msg.status === "unread" 
                         // Unread: Light Mode = White + Blue Border, Dark = White/10
                         ? "bg-white dark:bg-white/10 border-blue-200 dark:border-blue-500/30 shadow-sm shadow-blue-500/5 ring-1 ring-blue-100 dark:ring-0" 
                         // Read: Light Mode = Slate-50 (Sedikit abu biar beda sama bg container)
                         : "bg-slate-50 dark:bg-white/5 border-slate-100 dark:border-white/5 hover:bg-white dark:hover:bg-white/10"
                       }
                     `}
                   >
                      <div className="flex justify-between items-start mb-3">
                         {/* Sender Info & Tag */}
                         <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold text-white shadow-sm
                               ${msg.tagColor === "orange" ? "bg-gradient-to-br from-orange-400 to-red-500" : 
                                 msg.tagColor === "purple" ? "bg-gradient-to-br from-purple-400 to-pink-500" : 
                                 msg.tagColor === "blue" ? "bg-gradient-to-br from-blue-400 to-cyan-500" :
                                 "bg-slate-400"}
                            `}>
                               {msg.sender.charAt(0)}
                            </div>
                            <div>
                               <div className="flex items-center gap-2">
                                 <h4 className={`text-sm ${msg.status === "unread" ? "font-black text-slate-900 dark:text-white" : "font-bold text-slate-700 dark:text-slate-300"}`}>
                                   {msg.sender}
                                 </h4>
                                 <span className={`text-[10px] px-2 py-0.5 rounded-md font-bold uppercase tracking-wider
                                    bg-${msg.tagColor}-100 text-${msg.tagColor}-700 dark:bg-${msg.tagColor}-500/20 dark:text-${msg.tagColor}-300
                                 `}>
                                   {msg.category}
                                 </span>
                               </div>
                               <span className="text-xs text-slate-500 dark:text-slate-400">
                                 {msg.status === "unread" ? "Mengirim pesan baru" : "Pesan telah dibaca"}
                               </span>
                            </div>
                         </div>

                         {/* Date */}
                         <div className="text-right">
                            <span className={`text-xs font-bold ${msg.status === "unread" ? "text-blue-600 dark:text-blue-400" : "text-slate-400"}`}>
                              {msg.date}
                            </span>
                         </div>
                      </div>

                      {/* Subject & Preview */}
                      <div className="pl-13 md:pl-13">
                        <div className="flex items-center justify-between">
                            <h3 className={`text-sm mb-1 ${msg.status === "unread" ? "font-bold text-slate-900 dark:text-white" : "font-medium text-slate-600 dark:text-slate-400"}`}>
                                {msg.subject}
                            </h3>
                            {msg.isStarred && <Star size={14} className="text-yellow-400 fill-current" />}
                        </div>
                        <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-relaxed">
                            {msg.preview}
                        </p>
                      </div>

                      {/* Action Buttons (Floating on Hover) */}
                      <div className="absolute right-4 bottom-4 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                         <button title="Balas" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-blue-500 text-slate-500 hover:text-blue-500 rounded-lg shadow-sm transition-colors">
                            <Reply size={14} />
                         </button>
                         {msg.status !== "done" && (
                           <button onClick={() => handleMarkDone(msg.id)} title="Selesai" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-green-500 text-slate-500 hover:text-green-500 rounded-lg shadow-sm transition-colors">
                              <CheckCircle size={14} />
                           </button>
                         )}
                         <button onClick={() => handleDelete(msg.id)} title="Hapus" className="p-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-white/10 hover:border-red-500 text-slate-500 hover:text-red-500 rounded-lg shadow-sm transition-colors">
                            <Trash2 size={14} />
                         </button>
                      </div>

                   </motion.div>
                 ))
               ) : (
                 // Empty State
                 <div className="flex flex-col items-center justify-center h-96 text-center text-slate-400">
                    <div className="w-20 h-20 bg-slate-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4">
                       <Filter size={32} className="opacity-30" />
                    </div>
                    <p className="text-sm font-bold text-slate-600 dark:text-slate-300">Tidak ada pesan ditemukan</p>
                    <p className="text-xs mt-1">Coba ubah filter atau kata kunci pencarian</p>
                 </div>
               )}
             </AnimatePresence>
           </div>

        </div>

      </div>

    </div>
  );
}